// archivo: entities.cs
// función: define las entidades del dominio que representan las tablas y datos principales del sistema.

// espacio de nombres que organiza las clases del proyecto.
namespace AbarrotesInventory.Domain.Entities;

// clase principal de este archivo.
public class Role { public int Id {get;set;} public string Name {get;set;} = ""; public ICollection<User> Users {get;set;} = new List<User>(); }
public class User { public int Id {get;set;} public string Username {get;set;}=""; public string PasswordHash {get;set;}=""; public string FullName {get;set;}=""; public string Email {get;set;}=""; public bool Active {get;set;}=true; public int RoleId {get;set;} public Role? Role {get;set;} public ICollection<Sale> Sales {get;set;}=new List<Sale>(); public ICollection<Purchase> Purchases {get;set;}=new List<Purchase>(); }
public class Category { public int Id {get;set;} public string Name {get;set;}=""; public string? Description {get;set;} public bool Active {get;set;}=true; public ICollection<Product> Products {get;set;}=new List<Product>(); }
public class Supplier { public int Id {get;set;} public string Name {get;set;}=""; public string? TaxId {get;set;} public string? Phone {get;set;} public string? Email {get;set;} public string? Address {get;set;} public bool Active {get;set;}=true; public ICollection<Purchase> Purchases {get;set;}=new List<Purchase>(); }
public class Customer { public int Id {get;set;} public string Name {get;set;}=""; public string? Document {get;set;} public string? Phone {get;set;} public string? Email {get;set;} public string? Address {get;set;} public bool Active {get;set;}=true; public ICollection<Sale> Sales {get;set;}=new List<Sale>(); }
public class Product { public int Id {get;set;} public string Code {get;set;}=""; public string Name {get;set;}=""; public int CategoryId {get;set;} public Category? Category {get;set;} public decimal PurchasePrice {get;set;} public decimal SalePrice {get;set;} public int Stock {get;set;} public int MinStock {get;set;} public string Unit {get;set;}="UND"; public DateTime? ExpirationDate {get;set;} public bool Active {get;set;}=true; public ICollection<PurchaseDetail> PurchaseDetails {get;set;}=new List<PurchaseDetail>(); public ICollection<SaleDetail> SaleDetails {get;set;}=new List<SaleDetail>(); public ICollection<InventoryMovement> InventoryMovements {get;set;}=new List<InventoryMovement>(); }
public class Purchase { public int Id {get;set;} public string Number {get;set;}=""; public DateTime Date {get;set;}=DateTime.Now; public int SupplierId {get;set;} public Supplier? Supplier {get;set;} public int UserId {get;set;} public User? User {get;set;} public decimal Total {get;set;} public string Status {get;set;}="COMPLETED"; public ICollection<PurchaseDetail> Details {get;set;}=new List<PurchaseDetail>(); }
public class PurchaseDetail { public int Id {get;set;} public int PurchaseId {get;set;} public Purchase? Purchase {get;set;} public int ProductId {get;set;} public Product? Product {get;set;} public int Quantity {get;set;} public decimal UnitCost {get;set;} public decimal Subtotal {get;set;} }
public class Sale { public int Id {get;set;} public string Number {get;set;}=""; public DateTime Date {get;set;}=DateTime.Now; public int CustomerId {get;set;} public Customer? Customer {get;set;} public int UserId {get;set;} public User? User {get;set;} public decimal Subtotal {get;set;} public decimal Tax {get;set;} public decimal Total {get;set;} public string PaymentMethod {get;set;}="EFECTIVO"; public string Status {get;set;}="COMPLETED"; public ICollection<SaleDetail> Details {get;set;}=new List<SaleDetail>(); }
public class SaleDetail { public int Id {get;set;} public int SaleId {get;set;} public Sale? Sale {get;set;} public int ProductId {get;set;} public Product? Product {get;set;} public int Quantity {get;set;} public decimal UnitPrice {get;set;} public decimal Subtotal {get;set;} }
public class InventoryMovement { public int Id {get;set;} public int ProductId {get;set;} public Product? Product {get;set;} public DateTime Date {get;set;}=DateTime.Now; public string Type {get;set;}="ENTRY"; public int Quantity {get;set;} public int StockBefore {get;set;} public int StockAfter {get;set;} public string? Reference {get;set;} public string? Notes {get;set;} }
public class Payment { public int Id {get;set;} public int SaleId {get;set;} public Sale? Sale {get;set;} public DateTime Date {get;set;}=DateTime.Now; public decimal Amount {get;set;} public string Method {get;set;}="EFECTIVO"; }
